        'Обнаруживает лица с помощью OpenCV FaceDetectorYN и модели YuNet 2023 при пороге уверенности 0,85, затем расширяет каждую рамку на 18 процентов с каждой стороны, чтобы закрыть также волосы и линию подбородка.',
        'Скрывает каждое выбранное лицо размытием по Гауссу с ядром в треть размера рамки, мозаикой из 14 блоков по ширине рамки или черной заливкой.',
        'Предлагает три режима выбора: все обнаруженные лица, только отмеченные вами лица или все, кроме отмеченных.',
        'Хранит результаты обнаружения в 30-минутном сеансе, привязанном к SHA-256 вашего файла, чтобы применялись ровно те рамки, которые вы видели.',
        'Записывает новый JPG, PNG или WebP с теми же размерами в пикселях; исходная загрузка не изменяется.',
