        'Без сеанса обнаружения скрипт заново обнаруживает лица при запуске и закрывает каждое найденное; результат идентичен запуску «Обнаружить лица» с режимом «все».',
        'Результат записывается OpenCV, а шаг обратного копирования exiftool конвертера не выполняется для ИИ-результатов, поэтому результат не несет исходных тегов EXIF, GPS и камеры. Это все же не замена инструменту EXIF, который позволяет увидеть и выбрать, что удаляется.',
