      whenNotToUse: 'Не полагайтесь на этот инструмент там, где одно пропущенное лицо недопустимо, например при редактировании, предписанном законом; YuNet при пороге 0,85 пропускает лица, которые крошечные, отвернуты, в масках или в глубокой тени, и вы должны проверить результат сами. Не используйте легкое размытие на большом лице, если человек должен остаться неузнаваемым; используйте черный прямоугольник. Бейджи, номерные знаки и экраны — не лица, поэтому для них подходит инструмент скрытия текста или удаление объектов. А если ваша цель — полностью убрать человека из сцены, а не скрыть его лицо, это делает удаление объектов.',
