      intro: 'Скриншоты выдают то, что их владельцы перестали замечать: адрес электронной почты в заголовке, номер счета в таблице, номер телефона в пузыре чата. Эта страница читает каждый фрагмент текста на изображении с помощью EasyOCR на нашем собственном сервере и закрывает совпадения черным прямоугольником, размытием или пиксельной мозаикой. В режиме по умолчанию она закрывает только текст, который соответствует шаблонам персональных данных: адреса электронной почты, номера телефонов, номера в формате социального страхования, длинные последовательности цифр, похожие на номера карт, и почтовые адреса. В режиме «весь текст» она закрывает каждое слово, которое может прочитать, — более безопасный выбор, когда вы не можете предугадать, что на странице.',
