        'Сервер запускает redact_text_pii.py с --detect pii или all-text, --redaction blackbox, blur или pixelate и --gpu. Скрипт создает EasyOCR Reader для английского (единственный язык, передаваемый сегодня) и вызывает readtext для файла, который возвращает блок, текст и уверенность для каждой строки.',
        'Шаблоны PII — регулярные выражения: электронная почта (локальная часть, @, домен с точкой и TLD из 2+ букв); североамериканский номер телефона из 10 цифр с необязательными +1, скобками, точками, пробелами или дефисами; три, две и четыре цифры, разделенные дефисом или пробелом; от 13 до 19 цифр, необязательно разделенных пробелами или дефисами (номера карт); и номер дома, за которым следуют название и слово типа улицы. Шаблонов для личных имен, дат рождения и идентификаторов за пределами США нет.',
        'Каждый совпавший блок увеличивается на max(3, 0,08 x большее из его ширины и высоты) пикселей с каждой стороны и ограничивается границами изображения. Черный прямоугольник использует cv2.rectangle с черной заливкой; пикселизация уменьшает область до 12 блоков по ширине и масштабирует обратно методом ближайшего соседа; размытие использует гауссово ядро max(11, длинная сторона / 3), приведенное к нечетному.',
