      privacyNote: 'Распознавание и скрытие текста выполняются как локальный процесс EasyOCR и OpenCV на нашем собственном GPU-сервере; никакой внешний сервис OCR или ИИ не получает изображение, а распознанный текст используется только для решения, какие блоки закрыть, и не сохраняется. Загрузка находится в uploads/<jobId>/, а изображение со скрытиями — в outputs/<jobId>/, оба зарегистрированы в реестре хранения и удаляются по окончании срока. Файлы хранятся 24 часа для гостей; с бесплатным аккаунтом вы выбираете срок от 24 часов до 2 лет. Как и каждая стандартная загрузка изображения, файл также проходит наш автоматический анализ содержимого на том же сервере, где локальная модель компьютерного зрения пишет короткое описание, которое хранится с задачей и не передается третьим сторонам.',
